/// Менеджер загрузки файлов с поддержкой повторов
///
/// Обеспечивает надежную загрузку файлов через HTTP с автоматическими
/// повторами при временных сбоях. Поддерживает валидацию контрольных сумм
/// и прогресс-индикаторы.
///
/// # Examples
///
/// ```rust
/// let downloader = DownloadManager::new()
///     .with_retries(3)
///     .with_timeout(Duration::from_secs(30));
///
/// let result = downloader.download(
///     "https://example.com/file.zip",
///     "./downloads/file.zip"
/// ).await?;
/// ```
pub struct DownloadManager {
    /// Максимальное количество попыток загрузки
    max_retries: u32,
    /// Таймаут для каждой попытки
    timeout: Duration,
}

